/* app.js: the page. 3D cube (three.js r128, classic script), 2D net, controls, move queue, solver wiring.
 *
 * The truth is app.state (Uint8Array(54), Kociemba facelet order). The 3D scene and the net only re-colour from it.
 * All cube facts come from window.CUBE_TABLES (generated by python -m rubiks.export_web) through the cube logic
 * in solver.js; nothing about the cube is re-derived here. A face turn is animated by rotating the 9 cubies of
 * the layer about the face normal (angle from the tables); at the end of the animation the permutation is
 * applied to app.state, the cubies snap back to their home positions and the stickers are re-coloured. The
 * load-time check (verifyTables) proves that the rotated geometry equals the re-coloured one for all 18 moves.
 */
(function () {
  'use strict';

  const $ = function (id) { return document.getElementById(id); };
  const T = window.CUBE_TABLES;
  const RS = window.RubiksSolver;

  function fatal(msg) {
    const b = $('banner');
    b.textContent = msg;
    b.className = 'banner error';
    b.hidden = false;
  }
  if (!T || !RS) {
    fatal(!T ? 'cube-tables.js did not load. Regenerate it: python -m rubiks.export_web --out web/cube-tables.js --seed 20261012'
             : 'solver.js did not load.');
    return;
  }

  const logic = RS.createCubeLogic(T);
  const report = logic.verifyTables();

  // ----------------------------------------------------------------------------------------------------------
  // Settings (persisted when localStorage works; under file:// some browsers refuse it, which is fine)
  // ----------------------------------------------------------------------------------------------------------
  const STORE = 'rubiks-nn-web.';
  function load(key, dflt) {
    try { const v = window.localStorage.getItem(STORE + key); return v === null ? dflt : v; } catch (e) { return dflt; }
  }
  function save(key, value) {
    try { window.localStorage.setItem(STORE + key, value); } catch (e) { /* ignore */ }
  }

  const SPEEDS = { slow: 400, normal: 180, fast: 60 };

  const app = {
    state: Uint8Array.from(T.solved),
    undoStack: [],       // moves applied since the last Reset / Scramble / Random state / Load (Undo pops these)
    sinceSolved: [],     // moves since the cube was last solved; null when unknown (Random state / Load)
    origin: 'solved',    // where the current history starts (shown in the status)
    queue: [],           // pending items: {kind: 'move'|'undo'|'solution'|'call', m, onStart, fn}
    busy: false,         // the queue pump is running
    idleWaiters: [],
    playing: false,      // a solution is being played (controls locked)
    solving: false,      // a backend is working (controls locked)
    solution: null,      // {moves, source, ms, serverMs, solves, startState, index, done}
    lastSolve: null,     // text of the last solver result
    speed: SPEEDS[load('speed', 'normal')] ? load('speed', 'normal') : 'normal',
    pendingHalf: false,  // keyboard: "2" pressed, the next face letter is a half turn
    lastMoveIndex: -1,   // highlight of the latest history entry
    solveToken: null,    // {cancelled, controller} of the solve in progress
    play: null,          // {cancelled} of the playback in progress
    faceletsDirty: false, // the user edited the facelet field and has not loaded it yet
  };

  let view = null;       // the 3D view, or null when three.js / WebGL is unavailable (the net still works)

  const solvers = RS.createSolvers(logic, { remoteUrl: defaultRemoteUrl() });
  function solverById(id) {
    for (let i = 0; i < solvers.length; i++) if (solvers[i].id === id) return solvers[i];
    return null;
  }

  function defaultRemoteUrl() {
    // Served over http(s) (e.g. by python -m rubiks.serve, also from a phone on the LAN): same origin.
    // Opened as file://: the dev server's default address.
    if (/^https?:$/.test(window.location.protocol)) return new URL('/solve', window.location.href).href;
    return RS.RemoteSolver.DEFAULT_URL;
  }

  // ----------------------------------------------------------------------------------------------------------
  // 3D view
  // ----------------------------------------------------------------------------------------------------------
  function createView(stage, canvas) {
    const THREE = window.THREE;
    if (!THREE) return { view: null, reason: 'three.js did not load from cdnjs (offline?)' };
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
    } catch (e) {
      return { view: null, reason: 'WebGL is not available (' + (e && e.message ? e.message : e) + ')' };
    }
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 100);
    const cubeRoot = new THREE.Group();
    const pivot = new THREE.Group();
    scene.add(cubeRoot);
    cubeRoot.add(pivot);

    const CUBIE = 0.96;            // cubie edge (spacing 1): a black gap of 0.04 between cubies
    const STICKER = 0.84;          // sticker edge
    const LIFT = CUBIE / 2 + 0.004; // sticker plane just outside the cubie face
    const bodyGeo = new THREE.BoxGeometry(CUBIE, CUBIE, CUBIE);
    const bodyMat = new THREE.MeshBasicMaterial({ color: 0x121212 });
    const stickerGeo = new THREE.PlaneGeometry(STICKER, STICKER);
    const faceMats = T.colours.map(function (hex) {
      return new THREE.MeshBasicMaterial({ color: new THREE.Color(hex), polygonOffset: true,
                                           polygonOffsetFactor: -1, polygonOffsetUnits: -1 });
    });

    // 27 cubies, one box per position of {-1, 0, 1}^3; their home positions never change.
    const cubies = [];
    const byKey = new Map();
    for (let x = -1; x <= 1; x++) {
      for (let y = -1; y <= 1; y++) {
        for (let z = -1; z <= 1; z++) {
          const g = new THREE.Group();
          g.position.set(x, y, z);
          g.userData.home = [x, y, z];
          g.add(new THREE.Mesh(bodyGeo, bodyMat));
          cubeRoot.add(g);
          cubies.push(g);
          byKey.set(x + ',' + y + ',' + z, g);
        }
      }
    }
    // 54 stickers placed from the exported geometry (sticker_pos = cubie position, sticker_normal = outward).
    const zAxis = new THREE.Vector3(0, 0, 1);
    const stickers = T.sticker_pos.map(function (p, i) {
      const n = T.sticker_normal[i];
      const g = byKey.get(p[0] + ',' + p[1] + ',' + p[2]);
      if (!g) throw new Error('sticker ' + i + ' is not on a cubie position');
      const mesh = new THREE.Mesh(stickerGeo, faceMats[T.solved[i]]);
      mesh.position.set(n[0] * LIFT, n[1] * LIFT, n[2] * LIFT);
      mesh.quaternion.setFromUnitVectors(zAxis, new THREE.Vector3(n[0], n[1], n[2]));
      g.add(mesh);
      return mesh;
    });

    // Camera: orbit about the centre, dragged with mouse or touch (pointer events, with a touch fallback).
    const DEFAULT_YAW = 0.62;
    const DEFAULT_PITCH = 0.5;
    let yaw = DEFAULT_YAW;
    let pitch = DEFAULT_PITCH;
    let distance = 11.5;
    function placeCamera() {
      const cp = Math.cos(pitch);
      camera.position.set(distance * cp * Math.sin(yaw), distance * Math.sin(pitch), distance * cp * Math.cos(yaw));
      camera.lookAt(0, 0, 0);
    }

    let frameRequested = false;
    function renderNow() { renderer.render(scene, camera); }
    function requestRender() {
      if (frameRequested) return;
      frameRequested = true;
      window.requestAnimationFrame(function () { frameRequested = false; renderNow(); });
    }

    const hasAspectRatio = !!(window.CSS && window.CSS.supports && window.CSS.supports('aspect-ratio', '1 / 1'));
    function resize() {
      const w = Math.max(1, stage.clientWidth);
      if (!hasAspectRatio) stage.style.height = Math.round(Math.min(w, window.innerHeight * 0.7)) + 'px';
      const h = Math.max(1, stage.clientHeight);
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      distance = 11.5 / Math.min(1, camera.aspect);  // keep the whole cube in view on a tall canvas
      camera.updateProjectionMatrix();
      placeCamera();
      renderNow();
    }

    const DRAG = 0.008;  // radians per CSS pixel
    const LIMIT = 1.45;  // pitch limit (just short of the poles, where lookAt would flip)
    function dragBy(dx, dy) {
      yaw -= dx * DRAG;
      pitch = Math.max(-LIMIT, Math.min(LIMIT, pitch + dy * DRAG));
      placeCamera();
      requestRender();
    }
    canvas.style.touchAction = 'none';
    if (window.PointerEvent) {
      let active = null;
      let lx = 0;
      let ly = 0;
      canvas.addEventListener('pointerdown', function (e) {
        if (active !== null) return;
        active = e.pointerId; lx = e.clientX; ly = e.clientY;
        try { canvas.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
        e.preventDefault();
      });
      canvas.addEventListener('pointermove', function (e) {
        if (e.pointerId !== active) return;
        dragBy(e.clientX - lx, e.clientY - ly);
        lx = e.clientX; ly = e.clientY;
      });
      const end = function (e) { if (e.pointerId === active) active = null; };
      canvas.addEventListener('pointerup', end);
      canvas.addEventListener('pointercancel', end);
    } else {
      let lx = null;
      let ly = null;
      canvas.addEventListener('touchstart', function (e) {
        if (e.touches.length !== 1) return;
        lx = e.touches[0].clientX; ly = e.touches[0].clientY; e.preventDefault();
      }, { passive: false });
      canvas.addEventListener('touchmove', function (e) {
        if (lx === null || e.touches.length !== 1) return;
        dragBy(e.touches[0].clientX - lx, e.touches[0].clientY - ly);
        lx = e.touches[0].clientX; ly = e.touches[0].clientY; e.preventDefault();
      }, { passive: false });
      canvas.addEventListener('touchend', function () { lx = null; });
      let down = false;
      canvas.addEventListener('mousedown', function (e) { down = true; lx = e.clientX; ly = e.clientY; });
      window.addEventListener('mousemove', function (e) {
        if (!down) return;
        dragBy(e.clientX - lx, e.clientY - ly); lx = e.clientX; ly = e.clientY;
      });
      window.addEventListener('mouseup', function () { down = false; });
    }

    if (typeof window.ResizeObserver === 'function') new window.ResizeObserver(resize).observe(stage);
    else window.addEventListener('resize', resize);

    function sync(state) {
      for (let i = 0; i < stickers.length; i++) stickers[i].material = faceMats[state[i]];
      requestRender();
    }

    function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }  // easeInOutCubic

    /** Animate move m over ms; at the last frame call commit() (which updates app.state and re-colours),
     *  return the cubies to their home positions, and render once. Resolves after that frame. */
    function animate(m, ms, commit) {
      return new Promise(function (resolve, reject) {
        const n = T.face_normal[T.move_face[m]];
        const axis = new THREE.Vector3(n[0], n[1], n[2]);
        const angle = logic.turnAngle(m);
        const layer = cubies.filter(function (g) { return logic.inTurnedLayer(m, g.userData.home); });
        pivot.quaternion.identity();
        layer.forEach(function (g) { pivot.add(g); });
        const finish = function () {
          let err = null;
          try { commit(); } catch (e) { err = e; }
          pivot.quaternion.identity();
          layer.forEach(function (g) { cubeRoot.add(g); });
          renderNow();
          if (err) reject(err); else resolve();
        };
        if (!(ms > 0) || document.hidden) { finish(); return; }
        const t0 = window.performance.now();
        const step = function () {
          const t = Math.max(0, Math.min(1, (window.performance.now() - t0) / ms));
          if (t >= 1) { finish(); return; }
          pivot.quaternion.setFromAxisAngle(axis, angle * ease(t));
          renderNow();
          window.requestAnimationFrame(step);
        };
        window.requestAnimationFrame(step);
      });
    }

    function resetCamera() { yaw = DEFAULT_YAW; pitch = DEFAULT_PITCH; placeCamera(); requestRender(); }

    resize();
    return { view: { sync: sync, animate: animate, resetCamera: resetCamera, resize: resize }, reason: '' };
  }

  // ----------------------------------------------------------------------------------------------------------
  // 2D net
  // ----------------------------------------------------------------------------------------------------------
  const netCells = [];
  function buildNet() {
    const net = $('net');
    net.style.gridTemplateColumns = 'repeat(' + T.net_size[1] + ', var(--cell))';
    net.style.gridTemplateRows = 'repeat(' + T.net_size[0] + ', var(--cell))';
    for (let i = 0; i < logic.N; i++) {
      const cell = document.createElement('div');
      const rc = T.net_pos[i];
      cell.className = 'cell';
      cell.style.gridRow = String(rc[0] + 1);
      cell.style.gridColumn = String(rc[1] + 1);
      cell.title = T.facelet_names[i] + ' = facelet ' + i;
      const label = document.createElement('span');
      label.className = 'idx';
      label.textContent = String(i);
      cell.appendChild(label);
      net.appendChild(cell);
      netCells.push(cell);
    }
    // face letters on the centres when the indices are hidden
    T.centres.forEach(function (c, f) {
      const letter = document.createElement('span');
      letter.className = 'face-letter';
      letter.textContent = T.face_names[f];
      netCells[c].appendChild(letter);
    });
  }
  function syncNet(state) {
    for (let i = 0; i < netCells.length; i++) netCells[i].setAttribute('data-c', String(state[i]));
  }

  // ----------------------------------------------------------------------------------------------------------
  // Move queue
  // ----------------------------------------------------------------------------------------------------------
  function durationMs() { return SPEEDS[app.speed] || SPEEDS.normal; }

  /** Apply move m to the truth and update everything that shows it. kind 'undo' pops the undo stack. */
  function commitMove(m, kind) {
    app.state = logic.applyMove(app.state, m);
    if (kind === 'undo') {
      app.undoStack.pop();
      if (app.sinceSolved) {
        const h = app.sinceSolved;
        if (h.length && h[h.length - 1] === logic.inverseMove(m)) h.pop(); else h.push(m);
      }
    } else {
      app.undoStack.push(m);
      if (app.sinceSolved) app.sinceSolved.push(m);
    }
    if (logic.isSolved(app.state)) app.sinceSolved = [];
    app.lastMoveIndex = app.undoStack.length - 1;
    if (view) view.sync(app.state);
    refresh();
  }

  function enqueue(item) {
    app.queue.push(item);
    pump();
    refreshControls();
  }

  function delay(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  async function pump() {
    if (app.busy) return;
    app.busy = true;
    try {
      while (app.queue.length) {
        const item = app.queue.shift();
        if (item.kind === 'call') { item.fn(); continue; }
        let m = item.m;
        if (item.kind === 'undo') {           // lazy: undo whatever is on top when its turn comes
          if (!app.undoStack.length) continue;
          m = logic.inverseMove(app.undoStack[app.undoStack.length - 1]);
        }
        if (item.onStart) item.onStart();
        if (view) {
          await view.animate(m, durationMs(), function () { commitMove(m, item.kind); });
        } else {
          commitMove(m, item.kind);
          await delay(item.kind === 'solution' ? durationMs() : 0);  // no 3D: still step the net visibly
        }
      }
    } catch (e) {
      showMsg('move queue error: ' + (e && e.message ? e.message : e), 'error');
      app.queue = [];
      app.playing = false;  // the end-of-playback marker was dropped with the queue
      app.play = null;
    } finally {
      app.busy = false;
      const waiters = app.idleWaiters.splice(0);
      waiters.forEach(function (w) { w(); });
      refresh();
    }
  }

  function whenIdle() {
    if (!app.busy && !app.queue.length) return Promise.resolve();
    return new Promise(function (resolve) { app.idleWaiters.push(resolve); });
  }

  /** Drop pending moves, then wait for the move in flight to finish. */
  async function interrupt() {
    app.queue = app.queue.filter(function (it) { return it.kind === 'call'; });
    await whenIdle();
  }

  function locked() { return app.playing || app.solving; }

  /** Moves are queued or animating. Solve and Animate anyway also wait for this: the state they start from
   *  must be the state the queued moves lead to, not the one on screen now. */
  function queueBusy() { return app.busy || app.queue.length > 0; }

  // ----------------------------------------------------------------------------------------------------------
  // Actions
  // ----------------------------------------------------------------------------------------------------------
  function setState(state, opts) {
    app.state = Uint8Array.from(state);
    app.undoStack = opts.undoStack ? opts.undoStack.slice() : [];
    app.sinceSolved = logic.isSolved(app.state) ? [] : (opts.sinceSolved ? opts.sinceSolved.slice() : null);
    app.origin = opts.origin;
    app.lastMoveIndex = app.undoStack.length - 1;
    app.solution = null;
    setFaceletsDirty(false);
    if (view) view.sync(app.state);
    refresh();
  }

  function setFaceletsDirty(dirty) {
    app.faceletsDirty = dirty;
    $('facelets-hint').hidden = !dirty;
  }

  function doMove(m) {
    if (locked()) return;
    clearMsgIfInfo();
    enqueue({ kind: 'move', m: m });
  }

  function doUndo() {
    if (locked()) return;
    enqueue({ kind: 'undo' });
  }

  async function doReset() {
    if (locked()) return;
    await interrupt();
    setState(T.solved, { origin: 'solved', sinceSolved: [] });
    showMsg('reset to solved', 'info');
  }

  function seedFromField() {
    const text = $('seed').value.trim();
    if (text) return { seed: RS.seedFromText(text), given: true };
    const buf = new Uint32Array(1);
    if (window.crypto && window.crypto.getRandomValues) window.crypto.getRandomValues(buf);
    else buf[0] = Math.floor(Math.random() * 4294967296);
    return { seed: buf[0], given: false };
  }

  async function doScramble() {
    if (locked()) return;
    let depth = parseInt($('depth').value, 10);
    if (!Number.isFinite(depth) || depth < 1) depth = 20;
    depth = Math.min(depth, 200);
    $('depth').value = String(depth);
    await interrupt();
    const s = seedFromField();
    const moves = logic.scramble(RS.mulberry32(s.seed), depth);
    setState(logic.applySequence(T.solved, moves), {
      origin: 'scramble (seed ' + s.seed + ', depth ' + depth + ')', undoStack: moves, sinceSolved: moves,
    });
    $('scramble-text').textContent = 'Scramble seed ' + s.seed + (s.given ? '' : ' (random; type it in the seed field to repeat)') +
                                     ', depth ' + depth + ': ' + logic.formatMoves(moves);
    showMsg('scrambled: ' + depth + ' moves, seed ' + s.seed, 'info');
  }

  async function doRandomState() {
    if (locked()) return;
    await interrupt();
    const s = seedFromField();
    const k = Math.floor(RS.mulberry32(s.seed)() * T.uniform_states.length);
    setState(T.uniform_states[k], { origin: 'uniform random state #' + k + ' (seed ' + s.seed + ')' });
    $('scramble-text').textContent = 'Random state #' + k + ' of ' + T.uniform_states.length +
                                     ' uniformly random reachable states (seed ' + s.seed + ')';
    showMsg('random state #' + k + ': reverse history cannot solve it; use the remote solver', 'info');
  }

  function doApplyText() {
    if (locked()) return;
    let moves;
    try {
      moves = logic.parseMoves($('typed').value);
    } catch (e) {
      showMsg(e.message, 'error');
      return;
    }
    if (!moves.length) { showMsg('type moves such as: R U R\' U\'', 'warn'); return; }
    moves.forEach(function (m) { enqueue({ kind: 'move', m: m }); });
    showMsg('applying ' + moves.length + ' moves', 'info');
  }

  async function doLoadFacelets() {
    if (locked()) return;
    let state;
    try {
      state = logic.fromFaceletString($('facelets').value);
    } catch (e) {
      showMsg('cannot load: ' + e.message, 'error');
      return;
    }
    await interrupt();
    setState(state, { origin: 'loaded facelet string' });
    $('scramble-text').textContent = 'Loaded facelet string (reachability is checked by the remote solver, not here)';
    showMsg('state loaded', 'info');
  }

  async function doCopyFacelets() {
    const text = logic.toFaceletString(app.state);
    const field = $('facelets');
    field.value = text;
    setFaceletsDirty(false);
    let copied = false;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(text);
        copied = true;
      }
    } catch (e) { copied = false; }
    if (!copied) {
      try {
        field.focus();
        field.select();
        copied = document.execCommand('copy');
      } catch (e) { copied = false; }
    }
    if (copied) showMsg('facelet string copied', 'info');
    else { field.focus(); field.select(); showMsg('could not copy automatically; the text is selected', 'warn'); }
  }

  function currentSolver() {
    return solverById($('backend').value) || solvers[0];
  }

  async function doSolve() {
    if (locked() || queueBusy()) return;  // the button is disabled then as well
    const solver = currentSolver();
    if (solver.id === 'remote') solver.url = $('remote-url').value.trim() || defaultRemoteUrl();
    if (!solver.available) {
      showMsg(solver.label + ': ' + (solver.unavailableReason || 'not available'), 'warn');
      app.lastSolve = solver.id + ': ' + (solver.unavailableReason || 'not available');
      refresh();
      return;
    }
    if (solver.id === 'onnx') {
      const width = onnxWidth();
      if (width === null) { showMsg(onnxWidthMessage(), 'warn'); return; }
      solver.width = width;
      solver.modelUrl = $('onnx-model').value.trim() || null;
    }
    const token = { cancelled: false,
                    controller: typeof window.AbortController === 'function' ? new window.AbortController() : null };
    app.solveToken = token;
    app.solving = true;
    app.solution = null;
    refresh();
    showMsg('solving with ' + solver.label + '…', 'info');
    await whenIdle();  // the moves still queued belong to the state being solved
    if (token.cancelled) return;
    const state = Uint8Array.from(app.state);
    const context = { history: app.sinceSolved ? app.sinceSolved.slice() : null, logic: logic,
                      signal: token.controller ? token.controller.signal : null,
                      onProgress: function (text) {
                        if (app.solveToken === token && !token.cancelled) showProgress(text);
                      } };
    let res;
    try {
      res = await solver.solve(Uint8Array.from(state), context);
    } catch (e) {
      if (token.cancelled) return;
      endSolving(token);
      const msg = e && e.message ? e.message : String(e);
      app.lastSolve = solver.id + ': failed: ' + msg;
      showMsg(msg, e && e.code === 'cancelled' ? 'warn' : 'error');
      refresh();
      return;
    }
    if (token.cancelled) return;  // Stop was pressed; the answer is discarded
    endSolving(token);
    if (!logic.statesEqual(app.state, state)) {
      showMsg('the cube changed while the solver was working; press Solve again', 'warn');
      refresh();
      return;
    }
    if (!res || typeof res !== 'object') res = { moves: null, source: solver.id, ms: 0 };
    const check = RS.verifySolution(logic, state, res.moves);
    const ms = typeof res.ms === 'number' ? res.ms : 0;
    const timing = Math.round(ms) + ' ms' + (typeof res.serverMs === 'number' ? ' (server ' + Math.round(res.serverMs) + ' ms)' : '') +
                   (typeof res.loadMs === 'number' ? ' (+ ' + Math.round(res.loadMs) + ' ms loading the model)' : '') +
                   (typeof res.nodes === 'number' ? ', ' + res.nodes + ' nodes' : '');
    if (!check.valid) {
      app.lastSolve = (res.source || solver.id) + ': invalid answer, ' + timing;
      showMsg('solver returned an invalid move list (not move indices 0..' + (logic.NM - 1) + ')', 'error');
      refresh();
      return;
    }
    app.solution = { moves: res.moves.slice(), source: res.source || solver.id, ms: ms, solves: check.solves,
                     startState: state, index: -1, done: 0 };
    app.lastSolve = app.solution.source + ', ' + res.moves.length + ' moves, ' + timing + ', ' +
                    (check.solves ? 'verified' : 'DOES NOT SOLVE');
    if (!check.solves) {
      showMsg('solver returned a non-solving sequence (' + res.moves.length + ' moves)', 'error');
      refresh();
      return;
    }
    if (!res.moves.length) {
      showMsg('already solved: 0 moves', 'info');
      refresh();
      return;
    }
    showMsg('verified: ' + res.moves.length + ' moves solve the cube; playing', 'ok');
    playSolution();
  }

  async function playSolution() {
    const sol = app.solution;
    if (!sol || locked()) return;
    // Lock first (no new moves can be queued), let any queued moves finish, THEN compare the start state.
    const play = { cancelled: false };
    app.play = play;
    app.playing = true;
    refresh();
    await whenIdle();
    if (play.cancelled || app.solution !== sol || !logic.statesEqual(app.state, sol.startState)) {
      if (app.play === play) { app.play = null; app.playing = false; }
      if (!play.cancelled) showMsg('the cube changed since this solution was computed; press Solve again', 'warn');
      refresh();
      return;
    }
    sol.index = -1;
    sol.done = 0;
    sol.moves.forEach(function (m, k) {
      app.queue.push({ kind: 'solution', m: m, onStart: function () { sol.index = k; sol.done = k; renderSolution(); } });
    });
    app.queue.push({ kind: 'call', fn: function () {
      if (app.play === play) app.play = null;
      app.playing = false;
      if (sol.index >= 0) sol.done = sol.index + 1;
      sol.index = -1;
      const solvedNow = logic.isSolved(app.state);
      if (sol.solves && solvedNow) showMsg('solved in ' + sol.moves.length + ' moves', 'ok');
      else if (!solvedNow) showMsg('played ' + sol.done + ' of ' + sol.moves.length + ' moves; the cube is not solved', 'warn');
      refresh();
    } });
    refresh();
    pump();
  }

  function endSolving(token) {
    if (app.solveToken !== token) return;  // a newer Solve owns the flag
    app.solveToken = null;
    app.solving = false;
    showProgress('');
  }

  function doStop() {
    if (app.solving && app.solveToken) {
      const token = app.solveToken;
      token.cancelled = true;          // doSolve discards whatever the backend answers later
      if (token.controller) token.controller.abort();
      endSolving(token);
      app.lastSolve = 'cancelled';
      showMsg('solve cancelled', 'warn');
    }
    if (app.playing) {
      if (app.play) app.play.cancelled = true;  // also covers a playback still waiting for the queue to drain
      app.queue = app.queue.filter(function (it) { return it.kind !== 'solution'; });
      showMsg('playback stopped', 'warn');
    }
    refresh();
  }

  // ----------------------------------------------------------------------------------------------------------
  // UI rendering
  // ----------------------------------------------------------------------------------------------------------
  function showMsg(text, level) {
    const el = $('msg');
    el.textContent = text;
    el.className = 'msg ' + (level || 'info');
  }
  /** The solver's progress line (one line per search depth for the in-browser network); '' hides it. */
  function showProgress(text) {
    const el = $('progress');
    el.textContent = text || '';
    el.hidden = !text;
  }
  function clearMsgIfInfo() {
    const el = $('msg');
    if (/\binfo\b|\bok\b/.test(el.className)) { el.textContent = ''; el.className = 'msg'; }
  }

  function moveSpans(container, moves, opts) {
    container.textContent = '';
    const start = Math.max(0, moves.length - (opts.limit || moves.length));
    if (start > 0) {
      const more = document.createElement('span');
      more.className = 'more';
      more.textContent = '… ' + start + ' earlier ';
      container.appendChild(more);
    }
    for (let k = start; k < moves.length; k++) {
      const s = document.createElement('span');
      s.className = 'mv';
      if (k === opts.current) s.className += ' current';
      else if (opts.doneBefore !== undefined && k < opts.doneBefore) s.className += ' done';
      s.textContent = T.move_names[moves[k]];
      container.appendChild(s);
    }
    if (!moves.length) {
      const e = document.createElement('span');
      e.className = 'more';
      e.textContent = opts.empty || '(none)';
      container.appendChild(e);
    }
  }

  function renderSolution() {
    const sol = app.solution;
    const box = $('solution');
    const anyway = $('animate-anyway');
    if (!sol) {
      moveSpans(box, [], { empty: '(press Solve)' });
      $('solution-meta').textContent = '';
      anyway.hidden = true;
      return;
    }
    moveSpans(box, sol.moves, { current: app.playing ? sol.index : -1, doneBefore: app.playing ? sol.index : sol.done,
                                empty: '(0 moves: already solved)' });
    $('solution-meta').textContent = sol.source + ': ' + sol.moves.length + ' moves' +
                                     (sol.solves ? ', verified' : ', does NOT solve the cube');
    anyway.hidden = sol.solves || !sol.moves.length;
  }

  function renderHistory() {
    moveSpans($('history'), app.undoStack, { current: app.playing ? -1 : app.lastMoveIndex, limit: 120,
                                             empty: '(no moves yet)' });
  }

  function renderStatus() {
    const v = $('verify');
    v.textContent = report.summary + (report.ok ? '' : ' (see the banner)');
    v.className = report.ok ? 'ok' : 'bad';
    let since;
    if (logic.isSolved(app.state)) since = 'solved';
    else if (app.sinceSolved) since = app.sinceSolved.length + ' move' + (app.sinceSolved.length === 1 ? '' : 's') + ' since solved';
    else since = 'moves since solved: unknown (' + app.origin + ')' + (app.undoStack.length ? ' + ' + app.undoStack.length : '');
    $('since').textContent = since;
    $('last-solve').textContent = 'last solve: ' + (app.lastSolve || '-');
  }

  function refreshControls() {
    const lock = locked();
    document.querySelectorAll('[data-lock]').forEach(function (el) { el.disabled = lock; });
    $('undo').disabled = lock || (!app.undoStack.length && !app.queue.length);
    $('stop').disabled = !lock;
    $('solve').disabled = lock || queueBusy();           // re-enabled by refresh() when the queue drains
    $('animate-anyway').disabled = lock || queueBusy();
    $('solve').textContent = app.solving ? 'Solving…' : (app.playing ? 'Playing…' : 'Solve');
    document.body.classList.toggle('is-locked', lock);
  }

  function refresh() {
    syncNet(app.state);
    if (!app.faceletsDirty) $('facelets').value = logic.toFaceletString(app.state);
    renderHistory();
    renderSolution();
    renderStatus();
    refreshControls();
  }

  // ----------------------------------------------------------------------------------------------------------
  // Controls
  // ----------------------------------------------------------------------------------------------------------
  function buildMoveButtons() {
    const box = $('moves');
    for (let f = 0; f < logic.NF; f++) {
      const group = document.createElement('div');
      group.className = 'face-group';
      group.setAttribute('data-c', String(T.solved[T.centres[f]]));
      for (let m = 0; m < logic.NM; m++) {
        if (T.move_face[m] !== f) continue;
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'btn move';
        b.textContent = T.move_names[m];
        b.setAttribute('data-lock', '');
        b.setAttribute('aria-label', 'turn ' + T.move_names[m]);
        b.addEventListener('click', function () { doMove(m); });
        group.appendChild(b);
      }
      box.appendChild(group);
    }
  }

  function buildBackendSelect() {
    const sel = $('backend');
    solvers.forEach(function (s) {
      const o = document.createElement('option');
      o.value = s.id;
      o.textContent = s.label + (s.available ? '' : ' (' + s.unavailableReason + ')');
      sel.appendChild(o);
    });
    const saved = load('backend', 'history');
    sel.value = solvers.some(function (s) { return s.id === saved; }) ? saved : 'history';
    const onChange = function (announce) {
      const s = currentSolver();
      save('backend', s.id);
      $('remote-row').hidden = s.id !== 'remote';
      $('onnx-row').hidden = s.id !== 'onnx';
      if (announce && !s.available) showMsg(s.label + ': ' + s.unavailableReason, 'warn');
      else if (announce) clearMsgIfInfo();
    };
    sel.addEventListener('change', function () { onChange(true); });
    onChange(false);
    const remote = solverById('remote');
    if (remote) $('remote-url').value = remote.url;
    $('remote-url').placeholder = defaultRemoteUrl();
    const width = $('onnx-width');
    width.min = String(RS.OnnxSolver.WIDTH_MIN);
    width.max = String(RS.OnnxSolver.WIDTH_MAX);
    width.value = load('onnxWidth', String(RS.OnnxSolver.WIDTH_DEFAULT));
    if (onnxWidth() === null) width.value = String(RS.OnnxSolver.WIDTH_DEFAULT);
    width.addEventListener('change', function () {
      const w = onnxWidth();
      if (w === null) { showMsg(onnxWidthMessage(), 'warn'); return; }
      save('onnxWidth', String(w));
      clearMsgIfInfo();
    });
    $('onnx-model').value = load('onnxModel', '');
    $('onnx-model').addEventListener('change', function () { save('onnxModel', $('onnx-model').value.trim()); });
  }

  /** The in-browser network's beam width setting, or null when it is not a whole number in range. */
  function onnxWidth() {
    const text = $('onnx-width').value.trim();
    const w = /^\d+$/.test(text) ? Number(text) : NaN;
    return Number.isInteger(w) && w >= RS.OnnxSolver.WIDTH_MIN && w <= RS.OnnxSolver.WIDTH_MAX ? w : null;
  }
  function onnxWidthMessage() {
    return 'beam width must be a whole number from ' + RS.OnnxSolver.WIDTH_MIN + ' to ' + RS.OnnxSolver.WIDTH_MAX;
  }

  function buildSpeed() {
    document.querySelectorAll('input[name="speed"]').forEach(function (r) {
      r.checked = r.value === app.speed;
      r.addEventListener('change', function () { if (r.checked) { app.speed = r.value; save('speed', r.value); } });
    });
  }

  const THEMES = ['auto', 'light', 'dark'];
  function applyTheme(t) {
    if (t === 'light' || t === 'dark') document.documentElement.setAttribute('data-theme', t);
    else document.documentElement.removeAttribute('data-theme');
    $('theme').textContent = 'Theme: ' + t;
  }

  function bindKeyboard() {
    document.addEventListener('keydown', function (e) {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const t = e.target;
      if (t && (t.isContentEditable || /^(TEXTAREA|SELECT)$/.test(t.tagName))) return;
      if (t && t.tagName === 'INPUT' && !/^(radio|checkbox|button|range)$/.test(t.type)) return;  // typing
      if (locked()) return;
      if (e.key === '2') { app.pendingHalf = true; $('key-hint').textContent = '2… (next face letter turns 180°)'; e.preventDefault(); return; }
      if (e.key === 'Escape') { app.pendingHalf = false; $('key-hint').textContent = ''; return; }
      if (e.key.length !== 1) return;
      const letter = e.key.toUpperCase();
      if (T.face_names.indexOf(letter) < 0) return;
      const name = letter + (app.pendingHalf ? '2' : (e.shiftKey ? "'" : ''));
      const m = logic.moveByName(name);
      app.pendingHalf = false;
      $('key-hint').textContent = '';
      if (m >= 0) { e.preventDefault(); doMove(m); }
    });
  }

  function bind() {
    $('undo').addEventListener('click', doUndo);
    $('reset').addEventListener('click', doReset);
    $('scramble').addEventListener('click', doScramble);
    $('random').addEventListener('click', doRandomState);
    $('solve').addEventListener('click', doSolve);
    $('stop').addEventListener('click', doStop);
    $('apply').addEventListener('click', doApplyText);
    $('typed').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); doApplyText(); } });
    $('load').addEventListener('click', doLoadFacelets);
    $('copy').addEventListener('click', doCopyFacelets);
    $('facelets').addEventListener('input', function () { setFaceletsDirty(true); });
    $('facelets').addEventListener('keydown', function (e) {
      if (e.key === 'Enter') { e.preventDefault(); doLoadFacelets(); }
      if (e.key === 'Escape') { setFaceletsDirty(false); refresh(); }
    });
    $('facelets-revert').addEventListener('click', function () { setFaceletsDirty(false); refresh(); });
    $('animate-anyway').addEventListener('click', function () {
      if (app.solution && !app.solution.solves) {
        showMsg('playing a sequence that does NOT solve the cube (' + app.solution.moves.length + ' moves)', 'warn');
        playSolution();
      }
    });
    $('view-reset').addEventListener('click', function () { if (view) view.resetCamera(); });
    $('show-idx').checked = load('showIdx', '0') === '1';
    const applyIdx = function () { $('net').classList.toggle('show-idx', $('show-idx').checked); };
    $('show-idx').addEventListener('change', function () { save('showIdx', $('show-idx').checked ? '1' : '0'); applyIdx(); });
    applyIdx();
    let theme = load('theme', 'auto');
    if (THEMES.indexOf(theme) < 0) theme = 'auto';
    applyTheme(theme);
    $('theme').addEventListener('click', function () {
      theme = THEMES[(THEMES.indexOf(theme) + 1) % THEMES.length];
      save('theme', theme);
      applyTheme(theme);
    });
    bindKeyboard();
  }

  // ----------------------------------------------------------------------------------------------------------
  // Start
  // ----------------------------------------------------------------------------------------------------------
  // Sticker colours for the net and the move-group markers, from the tables.
  T.colours.forEach(function (hex, c) { document.documentElement.style.setProperty('--sticker-' + c, hex); });

  if (!report.ok) {
    fatal('Cube tables FAILED verification: ' + report.summary + '. ' + report.errors.join('; ') +
          '. Regenerate web/cube-tables.js with python -m rubiks.export_web and reload.');
  }

  buildNet();
  buildMoveButtons();
  buildBackendSelect();
  buildSpeed();
  bind();

  try {
    const made = createView($('stage'), $('cube3d'));
    view = made.view;
    if (!view) {
      $('stage-note').textContent = '3D view unavailable: ' + made.reason + '. The 2D net and all controls still work.';
      $('stage-note').hidden = false;
      $('stage').classList.add('no-3d');
    }
  } catch (e) {
    view = null;
    $('stage-note').textContent = '3D view failed: ' + (e && e.message ? e.message : e) + '. The 2D net and all controls still work.';
    $('stage-note').hidden = false;
    $('stage').classList.add('no-3d');
  }
  if (view) view.sync(app.state);

  const g = T.generated;
  $('generated').textContent = 'tables: seed ' + g.seed + ', rubiks ' + g.package_version + ', numpy ' + g.numpy_version +
                               ', export ' + g.export_version + '; turn axes ' + report.turnsOk + '/' + report.turnsTotal +
                               ', ' + report.uniformTotal + ' uniform states';
  refresh();

  // For the console and for later automation: window.rubiksApp.state, .logic, .solvers, .enqueueMoves([...]).
  window.rubiksApp = {
    get state() { return Uint8Array.from(app.state); },
    logic: logic,
    solvers: solvers,
    report: report,
    enqueueMoves: function (moves) { moves.forEach(function (m) { enqueue({ kind: 'move', m: m }); }); },
  };
})();
